list_tax_profiles.code:
use WebCommander\Sdk\Resources\TaxProfiles\TaxProfiles;

$response = TaxProfiles::listTaxProfiles($client, ['limit' => 20]);

foreach ($response->map['tax_profiles'] as $profile) {
    echo $profile['id'], ' ', $profile['name'], $profile['default'] ? ' (default)' : '', PHP_EOL;
}
echo $response->map['pagination']['total'], ' tax profiles in total', PHP_EOL;

